import{c as t,Q as l,j as e,m as r}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"文件目录","description":"","frontmatter":{"title":"文件目录"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/文件管理/文件目录.md","filePath":"综合知识/系统基础/操作系统/文件管理/文件目录.md","lastUpdated":null}'),o={name:"综合知识/系统基础/操作系统/文件管理/文件目录.md"};function s(i,a,n,d,h,c){return l(),e("div",null,[...a[0]||(a[0]=[r('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 文件控制块（FCB）三类信息</li><li>[x] 文件目录概念</li><li>[x] 绝对路径与相对路径</li><li>[x] 目录损坏的影响</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="文件控制块-fcb" tabindex="-1">文件控制块（FCB） <a class="header-anchor" href="#文件控制块-fcb" aria-label="Permalink to &quot;文件控制块（FCB）&quot;">​</a></h3><p>文件控制块包含三类信息：</p><table tabindex="0"><thead><tr><th>类别</th><th>内容</th></tr></thead><tbody><tr><td><strong>基本信息类</strong></td><td>文件名、物理地址、文件长度、文件块数</td></tr><tr><td><strong>存取控制信息类</strong></td><td>文件存取权限（如 UNIX 的文件主/同组/一般用户的 RWX 权限）</td></tr><tr><td><strong>使用信息类</strong></td><td>建立日期、最后修改日期、最后访问日期、打开进程数、等待队列</td></tr></tbody></table><p><strong>文件目录</strong> = 文件控制块的有序集合。</p><h3 id="文件路径" tabindex="-1">文件路径 <a class="header-anchor" href="#文件路径" aria-label="Permalink to &quot;文件路径&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/3ea69ae9b9c1fa7caa37f67e35ad7204_MD5.png" alt="文件目录结构"></p><ul><li><strong>绝对路径</strong>：从根目录开始的路径</li><li><strong>相对路径</strong>：从当前路径开始的路径</li><li><strong>全文件名</strong> = 绝对路径 + 文件名（绝对路径和相对路径不含最后的文件名）</li></ul><h3 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h3><h4 id="路径判断" tabindex="-1">路径判断 <a class="header-anchor" href="#路径判断" aria-label="Permalink to &quot;路径判断&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20241020213306.png" alt="目录结构|600"></p><p>当前工作目录为 swshare，要访问 Fault.swf：</p><ul><li>全文件名：<code>\\swshare\\flash\\fault.swf</code></li><li>相对路径：<code>flash\\</code>，绝对路径：<code>\\swshare\\flash\\</code></li></ul><h4 id="掉电影响-🚩" tabindex="-1">掉电影响 🚩 <a class="header-anchor" href="#掉电影响-🚩" aria-label="Permalink to &quot;掉电影响 🚩&quot;">​</a></h4><p>系统正将文件修改结果写回磁盘时发生掉电，影响最大的是？</p><p>答案：<strong>目录文件</strong></p><p>解析：目录是文件控制块的集合，记录了文件系统的结构和文件各种信息。目录损坏会导致整个文件系统结构不稳定，系统无法正确访问和管理文件，影响远大于单个数据文件损坏。</p><h2 id="练习题-1" tabindex="-1">练习题 <a class="header-anchor" href="#练习题-1" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q107] 绝对路径</strong></p><p>在树形目录结构中，绝对路径与相对路径的根本区别在于起始点不同，绝对路径的起始点是（ ）。</p><ul><li>A. 当前工作目录</li><li>B. 父目录</li><li>C. 根目录</li><li>D. 用户主目录</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：绝对路径从根目录「/」开始；相对路径从当前工作目录开始。</p></div></details>',24)])])}const b=t(o,[["render",s]]);export{p as __pageData,b as default};
